CREATE TYPE public.app_role AS ENUM ('admin','user');
CREATE TABLE public.user_roles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid REFERENCES auth.users(id) ON DELETE CASCADE NOT NULL, role public.app_role NOT NULL, UNIQUE(user_id,role));
GRANT SELECT ON public.user_roles TO authenticated;
GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.has_role(_user_id uuid,_role public.app_role) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=_user_id AND role=_role) $$;
REVOKE ALL ON FUNCTION public.has_role(uuid,public.app_role) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.has_role(uuid,public.app_role) TO authenticated;
CREATE POLICY "Read own role" ON public.user_roles FOR SELECT TO authenticated USING (user_id=auth.uid());
GRANT SELECT,UPDATE ON public.inquiries TO authenticated;
GRANT SELECT ON public.contact_messages TO authenticated;
CREATE POLICY "Admin inquiry read" ON public.inquiries FOR SELECT TO authenticated USING(public.has_role(auth.uid(),'admin'));
CREATE POLICY "Admin inquiry update" ON public.inquiries FOR UPDATE TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE POLICY "Admin messages read" ON public.contact_messages FOR SELECT TO authenticated USING(public.has_role(auth.uid(),'admin'));
CREATE TABLE public.quotations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), inquiry_id uuid NOT NULL REFERENCES public.inquiries(id), amount numeric NOT NULL CHECK(amount>0), currency text NOT NULL DEFAULT 'INR' CHECK(currency='INR'), scope text NOT NULL, timeline text NOT NULL, terms text NOT NULL DEFAULT '', created_by uuid NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT ON public.quotations TO authenticated;
GRANT ALL ON public.quotations TO service_role;
ALTER TABLE public.quotations ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Admins read quotations" ON public.quotations FOR SELECT TO authenticated USING(public.has_role(auth.uid(),'admin'));
CREATE POLICY "Admins create quotations" ON public.quotations FOR INSERT TO authenticated WITH CHECK(public.has_role(auth.uid(),'admin') AND created_by=auth.uid());
CREATE TABLE public.site_content (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), kind text NOT NULL CHECK(kind IN ('service','portfolio','team')), key text NOT NULL, title text NOT NULL, description text NOT NULL DEFAULT '', image text NOT NULL DEFAULT '', category text NOT NULL DEFAULT '', items jsonb NOT NULL DEFAULT '[]', published boolean NOT NULL DEFAULT false, sort_order integer NOT NULL DEFAULT 0, UNIQUE(kind,key));
GRANT SELECT ON public.site_content TO anon;
GRANT SELECT,INSERT,UPDATE,DELETE ON public.site_content TO authenticated;
GRANT ALL ON public.site_content TO service_role;
ALTER TABLE public.site_content ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Published content" ON public.site_content FOR SELECT TO anon,authenticated USING(published=true);
CREATE POLICY "Admin all content" ON public.site_content FOR ALL TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE INDEX ON public.quotations(inquiry_id);
CREATE INDEX ON public.site_content(kind,sort_order);